-- global-remote-bookkeeper-for-usa-small-businesses-villieria (owner)
UPDATE businesses SET description = 'Global Remote Bookkeeper for USA Small Businesses, trading as QFIN Bookkeeping, is a remote bookkeeping practice based in Pretoria. It serves businesses in the USA, the UK and South Africa, and its bookkeeping services are delivered remotely. The practice handles accounts payable and receivable, bank and credit-card reconciliations, general-ledger review, journal entries and month-end close. It also provides management reporting, QuickBooks Online migrations and accounting-system support across platforms including QuickBooks Online, Xero, Sage Accounting and FreshBooks. Its founder has more than 23 years of accounting experience, including 18 years at a South African Chartered Accountant firm. The practice holds QuickBooks Online ProAdvisor and Xero Advisor credentials.', description_enriched_at = datetime('now') WHERE slug = 'global-remote-bookkeeper-for-usa-small-businesses-villieria' AND description = 'Global Remote Bookkeeper for USA Small Businesses (trading as QFIN Bookkeeping Services) provides virtual bookkeeping for coaches, consultants and creative-industry small businesses in the UK, USA and South Africa.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
