UPDATE businesses SET description = 'Heatherdale Veterinary Clinic, at Plot 32 Rose Street in Heatherdale, Akasia, was founded in 2004 on an agricultural smallholding near Pretoria North. The clinic serves pet owners, providing consultations, vaccinations, surgery, emergency care, digital X-rays, dental care, grooming and boarding, and nutritional advice for dogs, cats, birds and other animals. Alongside conventional veterinary care, it offers homeopathy, acupuncture, herbal remedies and traditional Chinese veterinary medicine, and its acupuncture service also treats horses. The clinic''s veterinarian is qualified in veterinary homeopathy, completed in 2012, and in veterinary acupuncture with Chi Institute certification. Owners seeking conventional and complementary options can find both at one practice.', description_enriched_at = datetime('now') WHERE slug = 'heatherdale-veterinary-clinic-heatherdale' AND description = 'Heatherdale Veterinary Clinic in Heatherdale, Akasia has offered holistic animal care since 2004, combining conventional veterinary treatment with homeopathy, acupuncture and herbal remedies, with consultations available by appointment only.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
