-- isitshixo-business-solutions-brakfontein (owner)
UPDATE businesses SET description = 'ISITSHIXO Business Solutions, based in Brakfontein, Centurion, provides ERP solutions for small and medium-sized enterprises, with particular expertise in Sage. Its services cover ERP implementation, training, customisation, add-on modules and ongoing support. The firm works across Sage 300, Sage VIP, Norming, Peresoft, FlowCentric and Pacific TechSol, and it serves SMEs as well as larger and multinational implementations. The company states that it has at least 12 years of ERP implementation experience and that it is a Level 1 B-BBEE black-owned enterprise. In August 2025 it was awarded a contract by the National Energy Regulator of South Africa (NERSA) worth R5,851,458 over three years, covering Sage 300 ERP support and maintenance and the implementation of add-on modules.', description_enriched_at = datetime('now') WHERE slug = 'isitshixo-business-solutions-brakfontein' AND description = 'An ERP consulting firm in Brakfontein with over 12 years of experience implementing Sage-based solutions for small to mid-sized enterprises, offering solution design, training, data support and technical support.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
