UPDATE businesses SET description = 'IWESCO Specialised Contract Cleaning & On-Site Waste Management, headquartered at 212 Heinrich Avenue in Amandasig, Pretoria, provides contract cleaning and waste-control services. Its work covers industrial, commercial and specialised cleaning, as well as once-off and event cleaning. Services include deep cleaning, window cleaning, carpet and upholstery cleaning, waste management, hygiene solutions, pest control, garden services and wash-bay cleaning. Its on-site waste management service is offered alongside its cleaning work. Clients include factories, warehouses, construction sites and manufacturing plants. The company operates nationally in the major metropolitan areas of South Africa. It was founded in 1997, has introduced ISO 9001 quality management across its operations and holds ISO 14001 environmental accreditation.', description_enriched_at = datetime('now') WHERE slug = 'iwesco-specialised-contract-cleaning-on-site-waste-management-amandasig' AND description = 'A contract cleaning and waste management company in Amandasig serving industrial, commercial, retail, food and event sectors, offering deep cleaning, window and carpet cleaning, hygiene solutions and pest control.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
